CREATE VIEW v223428 AS SELECT MIN(CASE WHEN x12.COALESCE(x1.Name_exp_1, NULL) = 1 THEN (x12.COALESCE(x1.Name_exp_1, NULL) + x12.COALESCE(x1.Name_exp_1, NULL) - x12.COALESCE(x1.Name_exp_1, NULL)) ELSE (x12.COALESCE(x1.Name_exp_1, NULL) + x12.COALESCE(x1.Name_exp_1, NULL) - x12.COALESCE(x1.Name_exp_1, NULL)) END), MAX(FROM_UNIXTIME(1000000000.12345)), AVG(ROW_NUMBER() OVER (PARTITION BY x12.COALESCE(x1.Name_exp_1, NULL) ORDER BY (@f := x12.COALESCE(x1.Name_exp_1, NULL)), x12.COALESCE(x1.Name_exp_1, NULL), LEAD(x12.COALESCE(x1.Name_exp_1, NULL), 5, 7) OVER (ORDER BY x12.COALESCE(x1.Name_exp_1, NULL)))), SUM(x12.COALESCE(x1.Name_exp_1, NULL)), MIN(RANK() OVER (ORDER BY x12.COALESCE(x1.Name_exp_1, NULL))), MAX(x12.COALESCE(x1.Name_exp_1, NULL) + x12.COALESCE(x1.Name_exp_1, NULL) + x12.COALESCE(x1.Name_exp_1, NULL)), AVG(1), SUM(x12.COALESCE(x1.Name_exp_1, NULL)), MIN(x12.COALESCE(x1.Name_exp_1, NULL)), MAX(x12.COALESCE(x1.Name_exp_1, NULL)), AVG(x12.COALESCE(x1.Name_exp_1, NULL)), SUM(DISTINCT x12.COALESCE(x1.Name_exp_1, NULL) % 11) FROM v222114 AS x12